namespace RonSijm.FluidHumidifier.Factories.Budgets;

public class InnerBudgetExpressionFactory(Action<Humidifier.Budgets.BudgetTypes.Expression> factoryAction = null) : SubResourceFactory<Humidifier.Budgets.BudgetTypes.Expression>
{

    internal InnerBudgetExpressionFactory NotFactory { get; set; }

    internal InnerBudgetExpressionDimensionValuesFactory DimensionsFactory { get; set; }

    internal InnerBudgetCostCategoryValuesFactory CostCategoriesFactory { get; set; }

    internal InnerBudgetTagValuesFactory TagsFactory { get; set; }

    protected override Humidifier.Budgets.BudgetTypes.Expression Create()
    {
        var expressionResult = CreateExpression();
        factoryAction?.Invoke(expressionResult);

        return expressionResult;
    }

    private Humidifier.Budgets.BudgetTypes.Expression CreateExpression()
    {
        var expressionResult = new Humidifier.Budgets.BudgetTypes.Expression();

        return expressionResult;
    }
    public override void CreateChildren(Humidifier.Budgets.BudgetTypes.Expression result)
    {
        base.CreateChildren(result);

        result.Not ??= NotFactory?.Build();
        result.Dimensions ??= DimensionsFactory?.Build();
        result.CostCategories ??= CostCategoriesFactory?.Build();
        result.Tags ??= TagsFactory?.Build();
    }

} // End Of Class

